import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"调试","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/debugging.md","filePath":"zh/dev/debugging.md"}'),o={name:"zh/dev/debugging.md"};function l(i,e,c,d,p,r){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="调试" tabindex="-1">调试 <a class="header-anchor" href="#调试" aria-label="Permalink to &quot;调试&quot;">​</a></h1><h2 id="先读启动日志" tabindex="-1">先读启动日志 <a class="header-anchor" href="#先读启动日志" aria-label="Permalink to &quot;先读启动日志&quot;">​</a></h2><p>每个子系统在启动阶段打印一行 <code>.... OK</code>。最后一行没有打印出来 的就是你的故障子系统。捕获它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512 -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -serial file:boot.log -display none</span></span></code></pre></div><h2 id="客户机内工具" tabindex="-1">客户机内工具 <a class="header-anchor" href="#客户机内工具" aria-label="Permalink to &quot;客户机内工具&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; dmesg            (kernel ring buffer)</span></span>
<span class="line"><span>ush&gt; logcat           (live follow of the persistent log)</span></span>
<span class="line"><span>ush&gt; logctl           (log levels + filters)</span></span>
<span class="line"><span>ush&gt; health           (CPU/mem/tasks/IO + alarms)</span></span>
<span class="line"><span>ush&gt; exc              (exception self-test - proves the trap path)</span></span>
<span class="line"><span>ush&gt; crashlog         (past crash records on /etc)</span></span>
<span class="line"><span>ush&gt; dumpinfo         (crash dump details)</span></span></code></pre></div><h2 id="panic-路径" tabindex="-1">panic 路径 <a class="header-anchor" href="#panic-路径" aria-label="Permalink to &quot;panic 路径&quot;">​</a></h2><p>内核 panic 会把异常帧（寄存器 + 故障地址）转储到串口，并把一条 crashlog 写入 /etc。<code>crashtest</code> 触发一次故意的 panic - 在你 真正需要之前，先用它验证你的 /etc 卷与串口捕获接线正确。</p><h2 id="宿主机侧的内核调试" tabindex="-1">宿主机侧的内核调试 <a class="header-anchor" href="#宿主机侧的内核调试" aria-label="Permalink to &quot;宿主机侧的内核调试&quot;">​</a></h2><ul><li>调试符号：流水线以 <code>-g</code> 链接，然后剥离最终 ELF； <code>build/opencube_base.elf</code>（<code>strip</code> 之前、在 <code>make kernel</code> 期间产出）是你的符号载体。</li><li>在 QEMU 中：<code>-d int,cpu_reset -D qemu.log</code> 记录中断与复位； <code>-s -S</code> 加 gdb（<code>target remote localhost:1234</code>）给你经典的 远程调试循环。</li><li>可复现构建意味着复现两次的崩溃是<em>同一批字节</em> - 不会在多次 尝试之间出现海森 bug。</li></ul><h2 id="宿主机单元测试" tabindex="-1">宿主机单元测试 <a class="header-anchor" href="#宿主机单元测试" aria-label="Permalink to &quot;宿主机单元测试&quot;">​</a></h2><p><code>make test</code> 针对真实的内核源码编译并运行 <code>tests/host_*.c</code> 下的 测试桩（加密向量、tar、gzip、string、FAT 结构、在宿主机编译器 上开 ASAN 的 mbi 解析）。在这里迭代回归比启动循环快得多。</p><h2 id="已知的锋利边缘-来自审计记录" tabindex="-1">已知的锋利边缘（来自审计记录） <a class="header-anchor" href="#已知的锋利边缘-来自审计记录" aria-label="Permalink to &quot;已知的锋利边缘（来自审计记录）&quot;">​</a></h2><ul><li>4 GiB 以上的 xHCI DMA 会在探测和每次传输时被拒绝 - 如果一块 xHCI 设备消失了，检查你的 QEMU 内存大小。</li><li>ATA-DMA 对齐依赖堆的 32 字节块头；如果你改了 <code>mem_heap.c</code>， 运行 <code>fstest</code> + 一次 FAT32 挂载测试。</li><li>multiboot2 解析器会校验标签大小；测试里&quot;手搓&quot;的 mbi 必须遵守 每个标签的最小值，否则解析会提前停止。</li></ul>`,14)])])}const g=a(o,[["render",l]]);export{u as __pageData,g as default};
